mapper.select:
select o.*,u.name as user_name from orders o left join address_book ab on ab.id = o.address_book_id left join `user` u on u.id = o.user_id
o.status = #{status} and ab.phone like concat('%',#{phone},'%') and o.number like concat('%',#{number},'%') and o.order_time >= #{beginTime} and o.order_time <= #{endTime}
order by o.order_time desc

select id, name, order_id, dish_id, setmeal_id, dish_flavor, number, amount, image from order_detail where order_id in
#{orderId}
order by id
